[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>IPL 2026 Ball-by-Ball Analytics Report</title>
<style>
  :root {
    --navy: #0a1628;
    --navy-light: #0d2044;
    --blue: #1565c0;
    --accent: #ff6d00;
    --gold: #ffd54f;
    --teal: #00acc1;
    --green: #43a047;
    --red: #e53935;
    --text: #e8eaf6;
    --text-muted: #90a4ae;
    --card: #112240;
    --card-border: #1e3a5f;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: 'Segoe UI', Arial, sans-serif;
    background: var(--navy);
    color: var(--text);
    line-height: 1.6;
  }
  /* HEADER */
  header {
    background: linear-gradient(135deg, #0d2044 0%, #0a1628 50%, #1a0a2e 100%);
    padding: 2.5rem 2rem 2rem;
    border-bottom: 3px solid var(--accent);
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  header::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: radial-gradient(ellipse at 50% -20%, rgba(255,109,0,0.15) 0%, transparent 60%);
  }
  header h1 {
    font-size: 2.2rem;
    font-weight: 800;
    color: #fff;
    letter-spacing: -0.5px;
    position: relative;
  }
  header h1 span { color: var(--accent); }
  header .subtitle {
    color: var(--text-muted);
    font-size: 0.95rem;
    margin-top: 0.4rem;
    position: relative;
  }
  header .meta {
    display: flex;
    justify-content: center;
    gap: 2rem;
    margin-top: 1rem;
    flex-wrap: wrap;
    position: relative;
  }
  header .meta-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.82rem;
    color: var(--text-muted);
  }
  header .meta-item strong { color: var(--gold); }
  /* MAIN */
  main { max-width: 1400px; margin: 0 auto; padding: 2rem 1.5rem; }
  /* SECTION */
  section { margin-bottom: 3rem; }
  .section-header {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 2px solid var(--card-border);
  }
  .section-num {
    background: var(--accent);
    color: #fff;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 0.85rem;
    flex-shrink: 0;
  }
  .section-header h2 {
    font-size: 1.35rem;
    font-weight: 700;
    color: #fff;
  }
  /* KPI DASHBOARD */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 1rem;
    margin-bottom: 2rem;
  }
  @media (max-width: 900px) { .kpi-grid { grid-template-columns: repeat(3, 1fr); } }
  @media (max-width: 600px) { .kpi-grid { grid-template-columns: repeat(2, 1fr); } }
  .kpi-card {
    background: var(--card);
    border: 1px solid var(--card-border);
    border-radius: 12px;
    padding: 1.25rem;
    text-align: center;
    position: relative;
    overflow: hidden;
    transition: transform 0.2s;
  }
  .kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
  }
  .kpi-card.orange::before { background: var(--accent); }
  .kpi-card.teal::before { background: var(--teal); }
  .kpi-card.gold::before { background: var(--gold); }
  .kpi-card.green::before { background: var(--green); }
  .kpi-card.red::before { background: var(--red); }
  .kpi-val {
    font-size: 2.2rem;
    font-weight: 800;
    line-height: 1;
    margin: 0.5rem 0 0.25rem;
  }
  .kpi-card.orange .kpi-val { color: var(--accent); }
  .kpi-card.teal .kpi-val { color: var(--teal); }
  .kpi-card.gold .kpi-val { color: var(--gold); }
  .kpi-card.green .kpi-val { color: var(--green); }
  .kpi-card.red .kpi-val { color: var(--red); }
  .kpi-label {
    font-size: 0.72rem;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-weight: 600;
  }
  .kpi-sub { font-size: 0.7rem; color: var(--text-muted); margin-top: 0.2rem; }
  /* CARDS / GRIDS */
  .card {
    background: var(--card);
    border: 1px solid var(--card-border);
    border-radius: 12px;
    padding: 1.5rem;
    margin-bottom: 1rem;
  }
  .card h3 {
    font-size: 1rem;
    font-weight: 700;
    color: var(--gold);
    margin-bottom: 1rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
  }
  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
  .three-col { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 1rem; }
  @media (max-width: 800px) { .two-col, .three-col { grid-template-columns: 1fr; } }
  /* TOURNAMENT OVERVIEW */
  .overview-stats {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1rem;
    margin-bottom: 1.5rem;
