    background: var(--card);
    border: 1px solid var(--card-border);
    border-radius: 10px;
    padding: 1rem;
    text-align: center;
  }
  .stat-box .num {
    font-size: 1.8rem;
    font-weight: 800;
    color: var(--teal);
  }
  .stat-box .lbl {
    font-size: 0.72rem;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-top: 0.2rem;
  }
  /* TABLES */
  table { width: 100%; border-collapse: collapse; font-size: 0.85rem; }
  thead th {
    background: var(--navy-light);
    padding: 0.6rem 0.75rem;
    text-align: left;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--text-muted);
    position: sticky;
    top: 0;
  }
  tbody tr {
    border-bottom: 1px solid rgba(255,255,255,0.04);
    transition: background 0.15s;
  }
  tbody tr:hover { background: rgba(255,255,255,0.04); }
  tbody td {
    padding: 0.55rem 0.75rem;
    color: var(--text);
  }
  .rank-badge {
    background: var(--navy-light);
    color: var(--text-muted);
    border-radius: 4px;
    padding: 0.1rem 0.4rem;
    font-size: 0.75rem;
    font-weight: 700;
  }
  .rank-badge.gold { background: rgba(255,213,79,0.2); color: var(--gold); }
  .rank-badge.silver { background: rgba(176,190,197,0.2); color: #b0bec5; }
  .rank-badge.bronze { background: rgba(161,116,75,0.2); color: #a1744b; }
  .team-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 700;
  }
  /* SVG CHARTS */
  .chart-wrap { overflow-x: auto; }
  svg text { font-family: 'Segoe UI', Arial, sans-serif; }
  /* BAR CHART */
  .bar-chart-container { position: relative; }
  /* PHASE BREAKDOWN */
  .phase-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
  @media (max-width: 700px) { .phase-grid { grid-template-columns: 1fr; } }
  .phase-card {
    border-radius: 10px;
    padding: 1.25rem;
    text-align: center;
    border: 1px solid;
  }
  .phase-card.pp { background: rgba(33,150,243,0.1); border-color: rgba(33,150,243,0.3); }
  .phase-card.mid { background: rgba(255,193,7,0.08); border-color: rgba(255,193,7,0.25); }
  .phase-card.death { background: rgba(244,67,54,0.1); border-color: rgba(244,67,54,0.3); }
  .phase-card .phase-rpo {
    font-size: 2.4rem;
    font-weight: 800;
    line-height: 1;
    margin: 0.5rem 0;
  }
  .phase-card.pp .phase-rpo { color: #2196f3; }
  .phase-card.mid .phase-rpo { color: #ffc107; }
  .phase-card.death .phase-rpo { color: #f44336; }
  .phase-card .phase-name {
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--text-muted);
    font-weight: 600;
  }
  .phase-card .phase-detail { font-size: 0.78rem; color: var(--text-muted); margin-top: 0.3rem; }
  /* EXTRAS VISUAL */
  .extras-bar { display: flex; height: 32px; border-radius: 6px; overflow: hidden; margin: 0.5rem 0; }
  .extras-seg { display: flex; align-items: center; justify-content: center; font-size: 0.7rem; font-weight: 700; transition: flex 0.3s; }
  /* HEATMAP */
  .heatmap-table td {
    text-align: center;
    font-size: 0.78rem;
    font-weight: 600;
    border-radius: 3px;
    padding: 0.4rem 0.6rem;
  }
  /* INSIGHT BOX */
  .insight {
    background: rgba(255,109,0,0.08);
    border-left: 3px solid var(--accent);
    padding: 0.75rem 1rem;
    border-radius: 0 8px 8px 0;
    font-size: 0.85rem;
    color: var(--text);
    margin-top: 1rem;
  }
  .insight strong { color: var(--accent); }
  /* FOOTER */
  footer {
    text-align: center;
    padding: 2rem;
    color: var(--text-muted);
    font-size: 0.78rem;
    border-top: 1px solid var(--card-border);
    margin-top: 2rem;
  }
  /* NAV */
  nav {
    position: sticky;
    top: 0;
    z-index: 100;
    background: rgba(10,22,40,0.95);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--card-border);
    padding: 0.6rem 2rem;
    display: flex;
    gap: 0.25rem;
    overflow-x: auto;
  }
  nav a {
    color: var(--text-muted);
    text-decoration: none;
    padding: 0.35rem 0.75rem;
    border-radius: 6px;
    font-size: 0.8rem;
    white-space: nowrap;
    transition: all 0.2s;
  }
  nav a:hover { background: rgba(255,255,255,0.08); color: var(--text); }
  /* DISMISSAL PIE placeholder */
  .donut-wrap { display: flex; align-items: center; gap: 2rem; }
  .donut-legend { display: flex; flex-direction: column; gap: 0.5rem; }
  .donut-legend-item { display: flex; align-items: center; gap: 0.5rem; font-size: 0.82rem; }
  .donut-dot { width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0; }
  .progress-bar-wrap { margin-bottom: 0.6rem; }
  .progress-label { display: flex; justify-content: space-between; font-size: 0.8rem; margin-bottom: 0.2rem; }
  .progress-track { height: 8px; background: rgba(255,255,255,0.06); border-radius: 4px; overflow: hidden; }
  .progress-fill { height: 100%; border-radius: 4px; }
  .tag {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 12px;
    font-size: 0.72rem;
    font-weight: 700;
    margin-left: 0.25rem;
  }
  .tag.up { background: rgba(67,160,71,0.2); color: #81c784; }
  .tag.down { background: rgba(229,57,53,0.2); color: #ef9a9a; }
  .tag.neutral { background: rgba(255,213,79,0.2); color: #ffd54f; }
</style>
</head>
